    var menu = new ContextMenuStrip();

    // Open Dashboard
    var dash = new ToolStripMenuItem("Open Dashboard");
    dash.Click += (s, e) => { Process.Start("http://127.0.0.1:" + Port); };
    menu.Items.Add(dash);
    menu.Items.Add(new ToolStripSeparator());

    // AutoStart toggle
    var auto = new ToolStripMenuItem("AutoStart");
    string startup = Environment.GetFolderPath(Environment.SpecialFolder.Startup) + "\\PrintPulseAgent.url";
    auto.Checked = File.Exists(startup);
    auto.Click += (s, e) => {
      if (auto.Checked) {
        try { File.Delete(startup); } catch {}
        auto.Checked = false;
      } else {
        try {
          string exe = Process.GetProcessById(AgentPid).MainModule.FileName;
          File.WriteAllText(startup, "[InternetShortcut]\nURL=file:///" + exe.Replace("\\", "/") + "\nIconIndex=0");
          auto.Checked = true;
        } catch {}
      }
    };
    menu.Items.Add(auto);
    menu.Items.Add(new ToolStripSeparator());

    // Quit
    var quit = new ToolStripMenuItem("Quit");
    quit.Click += (s, e) => {
      Quitting = true;
      Tray.Visible = false;
      Tray.Dispose();
      try {
        var req = WebRequest.Create("http://127.0.0.1:" + Port + "/api/quit");
        req.GetResponse();
      } catch {}
      try { Process.GetProcessById(AgentPid).Kill(); } catch {}
      Application.Exit();
    };
    menu.Items.Add(quit);

    Tray.ContextMenuStrip = menu;

    // Left-click opens dashboard
    Tray.Click += (s, e) => {
      if (((MouseEventArgs)e).Button == MouseButtons.Left)
        Process.Start("http://127.0.0.1:" + Port);
    };

    // Ping loop — exit if agent dies
    var timer = new Timer();
    timer.Interval = 5000;
    timer.Tick += (s, e) => {
      if (Quitting) return;
      try {
        var req = WebRequest.Create("http://127.0.0.1:" + Port + "/api/ping");
        req.GetResponse();
      } catch {
        Tray.Visible = false;
        Tray.Dispose();
        Application.Exit();
      }
    };
    timer.Start();

    Application.Run();
  }
